catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var deptGa = new GlideAjax('x_1921751_employ_0.RewardUtils');
    deptGa.addParam('sysparm_name', 'getDepartment');
    deptGa.addParam('sysparm_empid', newValue);
    deptGa.getXMLAnswer(function(answer) {
        g_form.setValue('department', answer);

		var dept = answer;
        var quarter = g_form.getValue('quarter');
        if (!dept || !quarter) return;

        var budgetGa = new GlideAjax('x_1921751_employ_0.RewardUtils');
        budgetGa.addParam('sysparm_name', 'getRemainingBudget');
        budgetGa.addParam('sysparm_dept', dept);
        budgetGa.addParam('sysparm_quarter', quarter);
        budgetGa.addParam('sysparm_year', new Date().getFullYear());
        budgetGa.getXMLAnswer(function(answer) {
            g_form.setValue('remaining_budget_display', answer);
        });
    });
}
